documents=[]; queries=[]
for topic,items in TOPICS.items():
 for i,(key,text,q1,q2) in enumerate(items):
  mid=f'{topic}-{key}'; split='test' if i>=4 else 'train' if i<3 else 'dev'
  documents.append({'id':mid,'group':mid,'split':split,'topic':topic,'text':text})
  for n,q in enumerate([q1,q2]): queries.append({'id':mid+f'-q{n}','text':q,'relevant':[mid],'split':split})
queries += [{'id':'unanswerable-'+str(i),'text':q,'relevant':[],'split':'test'} for i,q in enumerate(['Who founded Project Zorvia?','What is today\'s exact inflation rate?','What did I eat yesterday?','What color are the arrows in my diagram?'])]
path=Path(__file__).resolve().parents[1]/'data/corpus-v1.json'
path.write_text(json.dumps({'description':'Original synthetic development corpus. Not held-out real-world evidence. Splits frozen by concept/source group.','documents':documents,'queries':queries},indent=2)+'\n')
